import crypto from 'crypto';
import { EventEmitter } from 'events';

interface AuditEntry {
  timestamp: number;
  action: string;
  userId: string;
  resourceId: string;
  metadata: Record<string, unknown>;
}

interface CacheEntry<T> {
  value: T;
  expiresAt: number;
  etag: string;
}

class AuditLogger {
  private buffer: AuditEntry[] = [];
  private flushInterval: NodeJS.Timer;

  constructor(private readonly sink: (entries: AuditEntry[]) => Promise<void>) {
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  log(entry: AuditEntry): void {
    this.buffer.push(entry);
  }

  async flush(): Promise<void> {
    if (this.buffer.length === 0) return;
    const batch = [...this.buffer];
    this.buffer = [];
    await this.sink(batch);
  }

  destroy(): void {
    clearInterval(this.flushInterval);
  }
}

class TenantCache {
  private store = new Map<string, CacheEntry<unknown>>();

  computeKey(tenantId: string, resource: string, qualifier: string): string {
    const normalized = `${tenantId}:${resource}:${qualifier}`;
    return crypto.createHash('sha256').update(normalized).digest('hex').substring(0, 16);
  }

  get<T>(key: string): T | null {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }
    return entry.value as T;
  }

  set<T>(key: string, value: T, ttlMs: number): void {
    const etag = crypto.randomBytes(8).toString('hex');
    this.store.set(key, { value, expiresAt: Date.now() + ttlMs, etag });
  }

  invalidate(key: string): boolean {
    return this.store.delete(key);
  }
}

