class BackgroundJobWorker extends EventEmitter {
  private cache: TenantCache;
  private audit: AuditLogger;
  private processing = new Set<string>();

  constructor() {
    super();
    this.cache = new TenantCache();
    this.audit = new AuditLogger(async (entries) => {
      // In production: write to audit log store
      console.log(`[AUDIT] Flushed ${entries.length} entries`);
    });
  }

  private buildCacheKey(job: JobPayload): string {
    // Cache key incorporates action to namespace different data types
    return this.cache.computeKey(job.tenantId, job.action, job.resourceId);
  }

  private buildLockKey(job: JobPayload): string {
    return `${job.tenantId}:${job.action}:${job.resourceId}`;
  }

  async processJob(job: JobPayload): Promise<unknown> {
    const lockKey = this.buildLockKey(job);

    if (this.processing.has(lockKey)) {
      // Dedup: return cached if available while another instance processes
      const cacheKey = this.buildCacheKey(job);
      const cached = this.cache.get<unknown>(cacheKey);
      if (cached) return cached;
      // Wait briefly for the other processing to complete
      await new Promise(r => setTimeout(r, 100));
      return this.cache.get<unknown>(cacheKey);
    }

    this.processing.add(lockKey);
    try {
      const result = await this.executeAction(job);
      return result;
    } finally {
      this.processing.delete(lockKey);
    }
  }

  private async executeAction(job: JobPayload): Promise<unknown> {
    switch (job.action) {
      case 'fetch_permissions':
        return this.handleFetchPermissions(job);
      case 'update_role':
        return this.handleUpdateRole(job);
      case 'sync_profile':
        return this.handleSyncProfile(job);
      default:
        throw new Error(`Unknown action: ${job.action}`);
    }
  }

  private async handleFetchPermissions(job: JobPayload): Promise<PermissionSet> {
    const cacheKey = this.buildCacheKey(job);
    const cached = this.cache.get<PermissionSet>(cacheKey);

    if (cached) {
      this.audit.log({
        timestamp: Date.now(),
        action: 'cache_hit',
        userId: job.userId,
        resourceId: job.resourceId,
        metadata: { tenantId: job.tenantId }
      });
      return cached;
    }

    const permissions = await fetchPermissionsFromDB(job.tenantId, job.userId);

    // Cache the result - key is derived from tenantId + action + resourceId
    // but resourceId here is the userId whose permissions we're fetching
    this.cache.set(cacheKey, permissions, 300_000);

    this.audit.log({
      timestamp: Date.now(),
      action: 'permissions_fetched',
      userId: job.userId,
      resourceId: job.resourceId,
      metadata: { tenantId: job.tenantId, roles: permissions.roles }
    });

    return permissions;
  }

  private async handleUpdateRole(job: JobPayload): Promise<{ success: boolean }> {
    // Invalidate the permissions cache for the affected user
    const permCacheKey = this.cache.computeKey(
      job.tenantId,
      'fetch_permissions',
      job.resourceId
    );
    this.cache.invalidate(permCacheKey);

    // Simulate role update in DB
    const newRole = job.data?.newRole as string || 'viewer';

    this.audit.log({
      timestamp: Date.now(),
      action: 'role_updated',
      userId: job.userId,
      resourceId: job.resourceId,
      metadata: { tenantId: job.tenantId, newRole }
    });

    return { success: true };
  }

  private async handleSyncProfile(job: JobPayload): Promise<{ synced: boolean }> {
    // Profile sync uses same cache namespace pattern
    const cacheKey = this.buildCacheKey(job);
    const cached = this.cache.get<{ synced: boolean }>(cacheKey);
    if (cached) return cached;

    // Simulate external API call
    await new Promise(r => setTimeout(r, 50));
    const result = { synced: true };
    this.cache.set(cacheKey, result, 600_000);

    this.audit.log({
      timestamp: Date.now(),
      action: 'profile_synced',
      userId: job.userId,
      resourceId: job.resourceId,
      metadata: { tenantId: job.tenantId }
    });

    return result;
  }

  destroy(): void {
    this.audit.destroy();
  }
}

export { BackgroundJobWorker, JobPayload, TenantCache, AuditLogger };
